begin;
create schema subscription_test;
create function subscription_test.eq(actual bigint,expected bigint,label text) returns void language plpgsql as $$begin if actual is distinct from expected then raise exception 'FAIL % expected %, got %',label,expected,actual;end if;raise notice 'PASS %',label;end$$;
create function subscription_test.denied(statement text,label text) returns void language plpgsql as $$begin begin execute statement;exception when insufficient_privilege then raise notice 'PASS %',label;return;end;raise exception 'FAIL % unauthorized operation succeeded',label;end$$;
grant usage on schema subscription_test to anon,authenticated,castly_api;
grant execute on all functions in schema subscription_test to anon,authenticated,castly_api;
insert into auth.users(id,raw_user_meta_data) values('00000000-0000-0000-0000-000000000051','{}'),('00000000-0000-0000-0000-000000000052','{}');
update public.users set primary_role='talent' where id in ('00000000-0000-0000-0000-000000000051','00000000-0000-0000-0000-000000000052');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000051',true);
set local role authenticated;
select subscription_test.denied($$insert into public.subscription_grants(user_id,entitlement,source,source_key) values(auth.uid(),'creator_pro','google_play','mobile-forgery')$$,'mobile cannot grant premium');
select subscription_test.denied($$select * from public.subscription_orders$$,'mobile cannot read provider orders directly');
select subscription_test.denied($$insert into private.subscription_admins values(auth.uid())$$,'mobile cannot provision reviewer');
reset role;
set local role castly_api;
select subscription_test.eq((select count(*) from public.subscription_plans),2,'server catalog has two configurable plans');
select subscription_test.denied($$insert into public.subscription_grants(user_id,entitlement,source,source_key) values(private.request_user_id(),'creator_pro','google_play','unverified')$$,'unverified server transaction cannot grant');
select subscription_test.denied($$insert into public.subscription_entitlements(user_id,entitlement) values(private.request_user_id(),'creator_pro')$$,'unverified compatibility projection write denied');
select subscription_test.denied($$insert into private.subscription_admins values(private.request_user_id())$$,'server cannot provision reviewer');
select set_config('castly.subscription_verified','yes',true);
insert into public.subscription_grants(user_id,entitlement,source,source_key,expires_at) values(private.request_user_id(),'creator_pro','google_play','verified-fixture',now()+interval '1 month');
insert into public.subscription_orders(user_id,token_hash,product_id,state) values(private.request_user_id(),repeat('a',64),'fixture','pending');
select subscription_test.eq((select count(*) from public.subscription_grants),1,'verified server writes own ledger');
select set_config('castly.subscription_verified','',true);
with changed as(update public.subscription_orders set state='active' returning id) select subscription_test.eq((select count(*) from changed),0,'unverified order update denied');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000052',true);
select subscription_test.eq((select count(*) from public.subscription_grants),0,'other creator cannot read grants');
select subscription_test.eq((select count(*) from public.subscription_orders),0,'other creator cannot read orders');
select set_config('castly.subscription_verified','yes',true);
select subscription_test.denied($$insert into public.subscription_grants(user_id,entitlement,source,source_key) values('00000000-0000-0000-0000-000000000051','creator_pro','google_play','cross-user')$$,'verified context cannot grant another creator');
reset role;
select subscription_test.eq((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('subscription_plans','subscription_orders','subscription_events','subscription_grants','promotion_claims','subscription_audit_logs','subscription_discovery_eligibility') and c.relrowsecurity),7,'all subscription public tables have RLS');
rollback;
